const CATEGORY_CREATION_THEMES=['Família','Casa','Vida','Tecnologia','Finanças','Lazer','Transporte','Comidas e bebidas','Esporte','Ferramentas'];
const themeIconGroup=(theme:string)=>({Família:'Família',Casa:'Casa e vida',Vida:'Casa e vida',Tecnologia:'Tecnologia',Finanças:'Finanças e compras',Lazer:'Lazer',Transporte:'Transporte e viagem','Comidas e bebidas':'Comidas e bebidas',Esporte:'Esportes',Ferramentas:'Ferramentas'} as Record<string,string>)[theme]||theme;
const CATEGORY_ICONS:Record<string,string>={Salário:'💰',Alimentação:'🍽️',Mercado:'🛒',Restaurante:'🍴',Delivery:'🛵',Transporte:'🚗',Combustível:'⛽',Aluguel:'🏠',Condomínio:'🏢',Internet:'🌐',Luz:'💡',Água:'💧',Telefone:'📱',Saúde:'🩺',Educação:'📚',Filhos:'🧸',Viagens:'✈️',Lazer:'🎉',Compras:'🛍️',Assinaturas:'🔄',Investimentos:'📈',Dívidas:'📉',Seguros:'🛡️',Impostos:'🧾',Outros:'🏷️'};
const CATEGORY_ICON_GROUPS=[
  {name:'Família',icons:['👨‍👩‍👧‍👦','👶','🧒','👦','👧','👨','👩','👴','👵','🧸','❤️','🎁','🐶','🐱','🐾','🐕','🐈','🐰','🐦','🐟','🐹','🦜']},
  {name:'Casa e vida',icons:['🏠','🏡','🏢','🛋️','🛏️','🪑','🚪','🪞','🖼️','📺','🕰️','🕯️','🏮','💡','🪴','🛁','🚿','🚽','🧻','🧴','🧼','🪥','🧹','🧺','🪣','🍳','🥣','🍽️','🥄','🔪','☕','🫖','🧊','🔌','🔑','🧯']},
  {name:'Tecnologia',icons:['📱','💻','🖥️','⌨️','🖱️','🎧','🔌','🔋','📡','🌐','🤖','⌚']},
  {name:'Finanças e compras',icons:['💰','💵','💳','🪙','🏦','📈','📉','🧾','🛒','🛍️','🏷️','🎟️']},
  {name:'Lazer',icons:['🎉','🎮','🎲','🧩','🎬','📺','📚','🎨','🎭','🎪','🎁','⭐']},
  {name:'Transporte e viagem',icons:['🚗','🚌','🚕','🏍️','🚲','✈️','🚆','🚇','🚢','⛽','🧳','🗺️']},
  {name:'Comidas e bebidas',icons:['🍽️','🍴','🛒','🍔','🍕','🍣','🥗','🍎','☕','🥤','🍺','🍷']},
  {name:'Lugares e monumentos',icons:['🏥','🏫','🏪','🏨','🏛️','🏰','⛪','🗼','🗽','🏟️','🏖️','🏕️']},
  {name:'Esportes',icons:['⚽','🏀','🏐','🎾','🏈','🏊','🚴','🏋️','🥊','⛳','🏆','🥇']},
  {name:'Músicas e áudios',icons:['🎵','🎶','🎤','🎧','📻','🎸','🎹','🥁','🎷','🎺','🔊','💿']},
  {name:'Fotos e vídeos',icons:['📷','📸','🎥','📹','🎬','🖼️','📺','📱','💡','🎞️','📽️','🤳']},
  {name:'Natureza e animais',icons:['🌳','🌱','🌻','🌊','☀️','🌙','🐶','🐱','🐾','🐴','🐟','🦜']},
  {name:'Relógios',icons:['🕐','⏰','⌚','⏱️','⏳','📅','🗓️','⏲️']},
  {name:'Ferramentas',icons:['🔧','🔨','🪛','🛠️','⚙️','✂️','🔒','🧰','🪜','🧲','🔦','🧯']},
  {name:'Programação e computação',icons:['💻','🖥️','⌨️','🖱️','💾','🗄️','☁️','🔐','🤖','🧑‍💻','⚙️','🌐']},
];
const categoryIconFor=(category:string,fallback='🏷️')=>CATEGORY_ICONS[category]||fallback;
const appAction = (detail: string | { page: string }) => window.dispatchEvent(new CustomEvent('juntos-action', { detail }));
const systemDialog=(message:string,options:{title?:string;confirmLabel?:string;cancelLabel?:string;danger?:boolean;alert?:boolean}={})=>new Promise<boolean>(resolve=>window.dispatchEvent(new CustomEvent('juntos-dialog',{detail:{message,...options,resolve}})));
const confirmDialog=(message:string,title='Confirmar ação')=>systemDialog(message,{title,confirmLabel:'Confirmar',cancelLabel:'Cancelar',danger:/excluir|apagar|restaurar/i.test(message)});
const alertDialog=(message:string,title='Aviso')=>systemDialog(message,{title,confirmLabel:'Entendi',alert:true});
const displayPerson=(people:any,key:string)=>key==='Rafael'?people.Rafael.name.split(' ')[0]:key==='Mariana'?people.Mariana.name.split(' ')[0]:key;
const displayTitle=(people:any,title:string)=>title==='Salário Rafael'?'Salário '+people.Rafael.name.split(' ')[0]:title;

const menu = [
  ["Dashboard", LayoutDashboard], ["Transações", ReceiptText], ["Orçamentos", CircleDollarSign],
  ["Cartões", CreditCard], ["Calendário", CalendarDays], ["Metas", Target], ["Dívidas", Landmark],
  ["Assinaturas", Zap], ["App de compras", Search],
  ["Relatórios", TrendingUp], ["IA Conselheira", MessageCircleHeart],
] as const;

const transactions: any[] = [];


const expenses: any[] = [];
const cashflow: any[] = [];

function Avatar({ who, small = false, label }: { who: "R" | "M"; small?: boolean; label?: string }) {
  return <div className={`avatar ${small ? "small" : ""} ${who === "M" ? "mariana" : "rafael"}`}>{(label||who).trim().charAt(0).toUpperCase()}</div>;
}

function Logo() {
  return <div className="logo"><span><Heart size={17} fill="currentColor" /></span><div>Juntos <b>Finance</b></div></div>;
}

function MetricCard({ label, value, detail, icon: Icon, tone = "default", hide = false }: { label: string; value: string; detail?: string; icon: ComponentType<{size?: number}>; tone?: string; hide?: boolean }) {
  return <article className={`metric card ${tone}`}>
    <div className="metric-head"><span>{label}</span><i><Icon size={18} /></i></div>
    <strong>{hide ? "••••••" : value}</strong>
    {detail&&<small>{detail}</small>}
  </article>;
}

function NewTransactionButton({onSelect}:{onSelect:(type:string)=>void}){
  const [open,setOpen]=useState(false);
  return <div className="new-transaction-menu"><button className="primary" onClick={()=>setOpen(!open)} aria-expanded={open}><Plus size={18}/> Nova transação <ChevronDown size={16}/></button>{open&&<div className="new-transaction-options"><button onClick={()=>{onSelect('Receita');setOpen(false)}}><ArrowUpRight size={17}/><span><b>Receita</b><small>Registrar uma entrada</small></span></button><button onClick={()=>{onSelect('Despesa');setOpen(false)}}><ArrowDownLeft size={17}/><span><b>Despesa</b><small>Registrar um gasto</small></span></button><button onClick={()=>{onSelect('Transferência');setOpen(false)}}><Repeat2 size={17}/><span><b>Transferência</b><small>Mover dinheiro entre contas</small></span></button></div>}</div>;
}
function Dashboard({ onNew, onAi, hidden, onTogglePrivacy, people, currentName }: { onNew: (type?:string) => void; onAi: () => void; hidden: boolean; onTogglePrivacy:()=>void; people:any; currentName?:string }) {
  const [period,setPeriod]=useState(()=>new Intl.DateTimeFormat('en-CA').format(new Date()).slice(0,7));
  const [dashboardItems,setDashboardItems]=useState<any[]>([]);
  const [dashboardGoals,setDashboardGoals]=useState<any[]>([]);
  const [dashboardCards,setDashboardCards]=useState<any[]>([]);
  const [calendarEvents,setCalendarEvents]=useState<any[]>([]);
  const [customizing,setCustomizing]=useState(false);
  const [dashboardTransactionMenu,setDashboardTransactionMenu]=useState<number|null>(null);
  const [dashboardTransactionEditor,setDashboardTransactionEditor]=useState<any|null>(null);
  const [dashboardPrefs,setDashboardPrefs]=useState({metrics:true,invoices:true,insights:true,charts:true,activity:true,goals:true});
  const todayLabel=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).format(new Date()).replace(/^./,letter=>letter.toUpperCase());
  useEffect(()=>{const loadTransactions=()=>{const saved=localStorage.getItem('juntos-transactions');setDashboardItems(saved?JSON.parse(saved):transactions)};loadTransactions();window.addEventListener('juntos-transactions-updated',loadTransactions);return()=>window.removeEventListener('juntos-transactions-updated',loadTransactions)},[]);
  useEffect(()=>{const loadGoals=()=>{try{setDashboardGoals(JSON.parse(localStorage.getItem('juntos-goals')||'[]'))}catch{setDashboardGoals([])}};loadGoals();window.addEventListener('juntos-goals-updated',loadGoals);return()=>window.removeEventListener('juntos-goals-updated',loadGoals)},[]);
  useEffect(()=>{const loadCards=()=>{try{setDashboardCards(JSON.parse(localStorage.getItem('juntos-cards')||'[]'))}catch{setDashboardCards([])}};loadCards();window.addEventListener('juntos-cards-updated',loadCards);window.addEventListener('juntos-cloud-synced',loadCards);return()=>{window.removeEventListener('juntos-cards-updated',loadCards);window.removeEventListener('juntos-cloud-synced',loadCards)}},[]);
  useEffect(()=>{const load=()=>{try{setCalendarEvents(JSON.parse(localStorage.getItem('juntos-calendar-events')||'[]'));const saved=JSON.parse(localStorage.getItem('juntos-dashboard-prefs')||'null');if(saved)setDashboardPrefs(previous=>({...previous,...saved}))}catch{}};load();window.addEventListener('juntos-calendar-updated',load);window.addEventListener('juntos-cloud-synced',load);return()=>{window.removeEventListener('juntos-calendar-updated',load);window.removeEventListener('juntos-cloud-synced',load)}},[]);
  const toggleWidget=(key:keyof typeof dashboardPrefs)=>setDashboardPrefs(previous=>{const next={...previous,[key]:!previous[key]};localStorage.setItem('juntos-dashboard-prefs',JSON.stringify(next));return next});
const persistDashboardTransactions=(next:any[])=>{localStorage.setItem('juntos-transactions',JSON.stringify(next));setDashboardItems(next);window.dispatchEvent(new Event('juntos-transactions-updated'))};
  const editDashboardTransaction=(item:any,mode:'edit'|'value')=>{const createdAt=item.createdAt||`${item.dateInput||new Intl.DateTimeFormat('en-CA').format(new Date())}T12:00`;setDashboardTransactionEditor({mode,item,form:{...item,value:new Intl.NumberFormat('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(item.value)||0),createdAt:createdAt.slice(0,16)}});setDashboardTransactionMenu(null)};
  const saveDashboardTransaction=(event:React.FormEvent)=>{event.preventDefault();if(!dashboardTransactionEditor)return;const form=dashboardTransactionEditor.form;const value=Number(String(form.value).replace(/[.]/g,'').replace(',','.'));if(Number.isNaN(value)||value<0)return;const dateInput=(form.createdAt||'').slice(0,10)||form.dateInput;const date=dateInput?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(dateInput+'T12:00:00')).replace('.',''):form.date;persistDashboardTransactions(dashboardItems.map(item=>item.id===dashboardTransactionEditor.item.id?{...item,...form,value,dateInput,date}:item));setDashboardTransactionEditor(null);appAction('Transação atualizada com sucesso.')};
  const removeDashboardTransaction=async(item:any)=>{if(!await confirmDialog(`Excluir “${item.title}”?`))return;persistDashboardTransactions(dashboardItems.filter(entry=>entry.id!==item.id));setDashboardTransactionMenu(null);appAction('Transação excluída.')};
  const periodItems=dashboardItems.filter(item=>!item.dateInput||item.dateInput.startsWith(period));
  const monthIncome=periodItems.filter(item=>item.type==='in').reduce((total,item)=>total+Number(item.value||0),0);
  const monthExpense=periodItems.filter(item=>item.type==='out').reduce((total,item)=>total+Number(item.value||0),0);
  const monthSavings=monthIncome-monthExpense;
  const [selectedYear,selectedMonth]=period.split('-').map(Number);const previousDate=new Date(selectedYear,selectedMonth-2,1);const previousKey=previousDate.getFullYear()+'-'+String(previousDate.getMonth()+1).padStart(2,'0');const previousItems=dashboardItems.filter(item=>item.dateInput?.startsWith(previousKey));const previousResult=previousItems.filter(item=>item.type==='in').reduce((sum,item)=>sum+Number(item.value||0),0)-previousItems.filter(item=>item.type==='out').reduce((sum,item)=>sum+Number(item.value||0),0);const comparison=previousResult===0?(monthSavings===0?0:100):Math.round((monthSavings-previousResult)/Math.abs(previousResult)*100);
  const today=new Intl.DateTimeFormat('en-CA').format(new Date());const futureLimitDate=new Date();futureLimitDate.setDate(futureLimitDate.getDate()+30);const futureLimit=new Intl.DateTimeFormat('en-CA').format(futureLimitDate);const overdueLimitDate=new Date();overdueLimitDate.setDate(overdueLimitDate.getDate()-30);const overdueLimit=new Intl.DateTimeFormat('en-CA').format(overdueLimitDate);const futureTransactions=dashboardItems.filter(item=>item.type==='out'&&item.dateInput>=today&&item.dateInput<=futureLimit);const projectedBalance=monthSavings+futureTransactions.reduce((sum,item)=>sum+(item.type==='in'?Number(item.value||0):-Number(item.value||0)),0);const dueCalendarEvents=calendarEvents.filter(item=>item.type!=='income'&&item.date>=overdueLimit&&item.date<=futureLimit&&!item.paid).map(item=>({...item,dateInput:item.date,category:item.category||'Calendário'}));const upcomingPayments=[...dueCalendarEvents,...futureTransactions].sort((a,b)=>(a.dateInput||'').localeCompare(b.dateInput||'')).slice(0,5);const dueStatus=(dateInput:string)=>{const days=Math.ceil((new Date(dateInput+'T12:00:00').getTime()-new Date(today+'T12:00:00').getTime())/86400000);return days<0?{tone:'overdue',label:Math.abs(days)===1?'Vencida há 1 dia':`Vencida há ${Math.abs(days)} dias`}:days===0?{tone:'today',label:'Vence hoje'}:days<=3?{tone:'urgent',label:`Vence em ${days} ${days===1?'dia':'dias'}`}:days<=7?{tone:'warning',label:`Vence em ${days} dias`}:{tone:'upcoming',label:`Vence em ${days} dias`}};
  const chartColors=['#7f2854','#b76a8e','#d79ab6','#8f6bb2','#d39155','#4c8d7b','#6d7f9f'];
  const categoryTotals=Object.entries(periodItems.filter(item=>item.type==='out').reduce((groups:Record<string,number>,item:any)=>{groups[item.category||'Outros']=(groups[item.category||'Outros']||0)+Number(item.value||0);return groups},{})).sort((a,b)=>b[1]-a[1]);
  const categoryExpenses=categoryTotals.map(([name,value],index)=>({name,value,percentage:monthExpense?Math.round(value/monthExpense*100):0,color:chartColors[index%chartColors.length]}));
  const dashboardCashflow=Array.from({length:6},(_,offset)=>{const [year,month]=period.split('-').map(Number);const date=new Date(year,month-1-(5-offset),1);const key=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0');const items=dashboardItems.filter(item=>item.dateInput?.startsWith(key));return {m:new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(date).replace('.',''),receita:items.filter(item=>item.type==='in').reduce((sum,item)=>sum+Number(item.value||0),0),despesa:items.filter(item=>item.type==='out').reduce((sum,item)=>sum+Number(item.value||0),0)}});
  const periodOptions=Array.from({length:36},(_,i)=>{const date=new Date(2025+Math.floor(i/12),i%12,1);return {value:date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0'),label:new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(date).replace(/^./,x=>x.toUpperCase())}});
  return <>
    <section className="welcome">
      <div><p>{todayLabel}</p><h1>Olá, {(currentName||people.Rafael.name).trim().split(' ')[0]} <span>👋</span></h1><small>Seu dinheiro, seus planos, uma vida juntos.</small></div>
      <div className="welcome-actions">
        <label className="ghost period period-picker"><CalendarDays size={17}/><span>{periodOptions.find(x=>x.value===period)?.label}</span><ChevronDown size={16}/><select value={period} onChange={e=>setPeriod(e.target.value)} aria-label="Selecionar mês e ano">{periodOptions.map(x=><option value={x.value} key={x.value}>{x.label}</option>)}</select></label>
        <button className={`ghost privacy-toggle ${hidden ? 'active' : ''}`} onClick={onTogglePrivacy} aria-pressed={hidden} title={hidden?'Mostrar valores':'Ocultar valores'}>{hidden ? <Eye size={18}/> : <EyeOff size={18}/>}<span>{hidden?'Mostrar valores':'Modo privado'}</span></button><button className="ghost" onClick={()=>setCustomizing(!customizing)}><Settings size={17}/> Personalizar</button><NewTransactionButton onSelect={onNew}/>
      </div>
    </section>

    {customizing&&<section className="card dashboard-customizer"><div><b>Personalizar Dashboard</b><small>Escolha os painéis que deseja visualizar.</small></div>{Object.entries({metrics:'Resumo financeiro',invoices:'Faturas dos cartões',insights:'Comparação e projeção',charts:'Gráficos',activity:'Movimentações e alertas',goals:'Metas'}).map(([key,label])=><button className={`toggle-option ${dashboardPrefs[key as keyof typeof dashboardPrefs]?'active':''}`} onClick={()=>toggleWidget(key as keyof typeof dashboardPrefs)} key={key}><Check size={15}/>{label}</button>)}</section>}
    <div className="metrics-grid" style={{display:dashboardPrefs.metrics?'grid':'none'}}>
      <MetricCard label="Saldo em contas" value={brl(Math.max(0,monthSavings))} detail="Contas e PIX" icon={WalletCards} tone="balance" hide={hidden}/>
      <MetricCard label={`Receitas (${period})`} value={`+ ${brl(monthIncome)}`} detail="Salários e entradas" icon={ArrowUpRight} tone="positive" hide={hidden}/>
      <MetricCard label={`Despesas (${period})`} value={`- ${brl(monthExpense)}`} detail="Gastos registrados" icon={ArrowDownLeft} tone="negative" hide={hidden}/>
      <MetricCard label="Economia líquida" value={`${monthIncome>0?Math.max(0,Math.round(monthSavings/monthIncome*100)):0}%`} icon={Percent} tone="purple" hide={hidden}/>
    </div>

    {dashboardPrefs.invoices&&dashboardCards.length>0&&<section className="dashboard-invoices"><div className="section-title"><div><h3>Faturas dos cartões</h3><p>Valores atuais de cada cartão cadastrado</p></div><button className="text-button" onClick={()=>appAction({page:'Cartões'})}>Gerenciar <ArrowRight size={15}/></button></div><div className="dashboard-invoice-grid">{dashboardCards.map(item=>{const invoice=Number(item.invoice)||0;const limit=Number(item.limit)||0;const pct=Math.min(100,Math.round(invoice/limit*100)||0);return <button className="card dashboard-invoice" key={item.id} onClick={()=>appAction({page:'Cartões'})}><span className="card-bank-brand">{item.bankDomain&&<img src={bankLogo(item.bankDomain)} alt=""/>}<b>{item.bank}</b><i className={invoice>0?'open':'closed'}>{invoice>0?'Aberta':'Fechada'}</i></span><strong>{hidden?'••••':brl(invoice)}</strong><small>{hidden?'Valores ocultos':<>de {brl(limit)} · {pct}% usado</>}</small><div><span style={{width:`${pct}%`}}/></div></button>})}</div></section>}
    <div className="metrics-grid compact dashboard-insights" style={{display:dashboardPrefs.insights?'grid':'none'}}><MetricCard label="Comparação mensal" value={`${comparison>=0?'+':''}${comparison}%`} detail={`Resultado anterior: ${brl(previousResult)}`} icon={comparison>=0?TrendingUp:TrendingDown} tone={comparison>=0?'positive':'negative'}/><MetricCard label="Saldo projetado em 30 dias" value={brl(projectedBalance)} detail={`${futureTransactions.length} lançamentos futuros`} icon={TrendingUp} tone="purple"/></div>
    <div className="content-grid charts-row" style={{display:dashboardPrefs.charts?'grid':'none'}}>
      <section className="card chart-card wide cashflow-bars">
        <div className="section-title"><div><h3>Receitas vs Despesas</h3></div></div>
        <div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><ReBarChart data={dashboardCashflow} margin={{top:12,right:8,left:8,bottom:0}} barGap={5} barCategoryGap="16%"><CartesianGrid vertical={false} stroke="#eee7eb"/><XAxis dataKey="m" axisLine={false} tickLine={false} tick={{fill:'#6f686c',fontSize:11}}/><YAxis hide/><Tooltip cursor={{fill:'rgba(112,34,68,.04)'}} itemSorter={(item)=>item.dataKey === 'receita' ? -1 : 1} formatter={(v,name)=>[brl(Number(v)),String(name)]}/><Bar dataKey="receita" name="Receita" fill="#2f9961" radius={[6,6,0,0]} maxBarSize={72}/><Bar dataKey="despesa" name="Despesa" fill="#8b263f" radius={[6,6,0,0]} maxBarSize={72}/></ReBarChart></ResponsiveContainer></div>
        <div className="legend bar-legend"><span><i className="income-bar"/>Receita</span><span><i className="expense-bar"/>Despesa</span></div>
      </section>
      <section className="card chart-card donut-card">
        <div className="section-title"><div><h3>Gastos por categoria</h3><p>{periodOptions.find(option=>option.value===period)?.label}</p></div><button className="icon-button" onClick={()=>appAction({page:'Transações'})} aria-label="Ver gastos por categoria"><MoreHorizontal size={19}/></button></div>
        <div className="donut-wrap"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={categoryExpenses} dataKey="value" innerRadius={54} outerRadius={78} paddingAngle={3} startAngle={90} endAngle={-270}>{categoryExpenses.map((x)=><Cell key={x.name} fill={x.color}/>)}</Pie><Tooltip formatter={(value)=>brl(Number(value))}/></PieChart></ResponsiveContainer><div className="donut-label"><b>{hidden?'••••':brl(monthExpense)}</b><small>Total gasto</small></div></div>
        <div className="expense-legend">{categoryExpenses.map(x=><div key={x.name}><span><i style={{background:x.color}}/>{x.name}</span><b>{x.percentage}%</b></div>)}</div>
      </section>
    </div>

    <div className="content-grid lower-row" style={{display:dashboardPrefs.activity?'grid':'none'}}>
      <section className="card transactions-card">
        <div className="section-title"><div><h3>Movimentações recentes</h3><p>Suas últimas transações</p></div><button className="text-button" onClick={()=>appAction({page:'Transações'})}>Ver todas <ArrowRight size={15}/></button></div>
        <div className="dashboard-transaction-list">{periodItems.length?periodItems.slice(0,5).map(t=><article className="dashboard-transaction" key={t.id}><div className={`transaction-icon ${t.type}`}>{categoryIconFor(t.category,t.icon)}</div><div className="dashboard-transaction-main"><b>{displayTitle(people,t.title)}</b><small>{t.notes||t.category||'Sem descrição'}</small></div><div className="dashboard-transaction-meta"><span><small>Titular</small><b>{displayPerson(people,t.person)}</b></span><span><small>Conta de onde saiu</small><b>{t.account||t.card||'Não informada'}</b></span><span><small>Lançamento</small><b>{t.createdAt?new Date(t.createdAt).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):`${t.date} · horário não informado`}</b></span></div><strong className={t.type}>{hidden?'••••':<>{t.type === "in" ? "+" : "−"} {brl(t.value)}</>}</strong><div className="dashboard-transaction-actions"><button className="icon-button" onClick={()=>setDashboardTransactionMenu(dashboardTransactionMenu===t.id?null:t.id)} aria-label="Ações da transação"><MoreHorizontal size={18}/></button>{dashboardTransactionMenu===t.id&&<div className="dashboard-transaction-menu"><button onClick={()=>editDashboardTransaction(t,'edit')}>Editar</button><button onClick={()=>editDashboardTransaction(t,'value')}>Alterar valor</button><button className="danger" onClick={()=>removeDashboardTransaction(t)}>Excluir</button></div>}</div></article>):<div className="organizer-empty">Nenhuma transação cadastrada.</div>}</div>
      </section>
      <aside className="side-stack">
        <section className="card ai-alerts-card"><div className="ai-alerts-head"><div><h3>Alertas da IA <span>0</span></h3><button onClick={onAi}>IA Conselheira <ChevronRight size={14}/></button></div></div><div className="ai-alert-list"><article><i className="alert-green"><Lightbulb size={18}/></i><div><b>Nenhum alerta por enquanto</b><p>Cadastre transações, contas e metas para receber análises.</p></div></article></div></section>
        <section className="card upcoming payment-alerts"><div className="section-title"><div><h3>Contas a vencer</h3><p>{upcomingPayments.length?`${upcomingPayments.length} alertas nos próximos 30 dias`:'Nenhuma conta próxima do vencimento'}</p></div></div>{upcomingPayments.length?upcomingPayments.map(item=>{const status=dueStatus(item.dateInput);return <button className={`payment-alert ${status.tone}`} onClick={()=>appAction({page:'Calendário'})} key={(item.id||item.title)+'-'+item.dateInput}><i><CalendarDays size={18}/></i><span><b>{item.title}</b><small>{item.category||'Conta'} · {new Date(item.dateInput+'T12:00:00').toLocaleDateString('pt-BR')}</small><em>{status.label}</em></span><strong>{hidden?'••••':item.value?brl(Number(item.value)):'—'}</strong></button>}):<p className="agenda-empty">Tudo em dia! Adicione vencimentos no Calendário para receber alertas.</p>}</section>
      </aside>
    </div>

    <section className="goals-section" style={{display:dashboardPrefs.goals?'block':'none'}}><div className="section-title"><div><h3>Minhas metas</h3><p>Transformando planos em conquistas</p></div><button className="text-button" onClick={()=>appAction({page:"Metas"})}>Ver todas <ArrowRight size={15}/></button></div><div className="goals-grid">{dashboardGoals.length?dashboardGoals.map(g=>{const pct=Math.round(g.current/g.total*100);return <article className="card goal" key={g.title}><div className="goal-top"><i>{g.emoji}</i><span><b>{g.title}</b><small>Meta para {g.date}</small></span><strong>{pct}%</strong></div><div className="progress"><span style={{width:`${pct}%`,background:g.color}}/></div><div className="goal-values"><b>{hidden ? "••••" : brl(g.current)}</b><span>de {hidden ? "••••" : brl(g.total)}</span></div></article>}):<div className="organizer-empty">Nenhuma meta cadastrada.</div>}</div></section>

    {dashboardTransactionEditor&&<div className="modal-backdrop" onMouseDown={event=>event.target===event.currentTarget&&setDashboardTransactionEditor(null)}><form className="modal dashboard-transaction-editor" onSubmit={saveDashboardTransaction}><div className="edit-modal-head"><div><span>MOVIMENTAÇÃO</span><h2>{dashboardTransactionEditor.mode==='value'?'Alterar valor':'Editar transação'}</h2><p>{dashboardTransactionEditor.item.title}</p></div><button type="button" className="icon-button" onClick={()=>setDashboardTransactionEditor(null)}><X/></button></div><div className="dashboard-transaction-form">{dashboardTransactionEditor.mode==='edit'&&<><label className="field-full">Título<input value={dashboardTransactionEditor.form.title||''} onChange={event=>setDashboardTransactionEditor({...dashboardTransactionEditor,form:{...dashboardTransactionEditor.form,title:event.target.value}})} required/></label><label className="field-full">Descrição<textarea value={dashboardTransactionEditor.form.notes||''} onChange={event=>setDashboardTransactionEditor({...dashboardTransactionEditor,form:{...dashboardTransactionEditor.form,notes:event.target.value}})} rows={3}/></label><label>Titular<select value={dashboardTransactionEditor.form.person||'Rafael'} onChange={event=>setDashboardTransactionEditor({...dashboardTransactionEditor,form:{...dashboardTransactionEditor.form,person:event.target.value}})}><option value="Rafael">Você</option><option value="Mariana">Parceiro(a)</option><option>Casal</option></select></label><label>Conta de onde saiu<input value={dashboardTransactionEditor.form.account||''} onChange={event=>setDashboardTransactionEditor({...dashboardTransactionEditor,form:{...dashboardTransactionEditor.form,account:event.target.value}})}/></label><label className="field-full">Data e hora<input type="datetime-local" value={dashboardTransactionEditor.form.createdAt||''} onChange={event=>setDashboardTransactionEditor({...dashboardTransactionEditor,form:{...dashboardTransactionEditor.form,createdAt:event.target.value}})}/></label></>}<label className={dashboardTransactionEditor.mode==='value'?'field-full':''}>Valor<input value={dashboardTransactionEditor.form.value||''} onChange={event=>setDashboardTransactionEditor({...dashboardTransactionEditor,form:{...dashboardTransactionEditor.form,value:formatMoneyInput(event.target.value)}})} inputMode="decimal" required/></label></div><div className="edit-modal-actions"><button type="button" className="ghost" onClick={()=>setDashboardTransactionEditor(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar alterações</button></div></form></div>}  </>;
}

function TransactionsPage({ onNew, people, isCouple }: { onNew: (type?:string) => void; people:any; isCouple:boolean }) {
  const [query,setQuery]=useState(''); const [person,setPerson]=useState('Todas'); const [period,setPeriod]=useState(()=>new Intl.DateTimeFormat('en-CA').format(new Date()).slice(0,7)); const [openMenu,setOpenMenu]=useState<number|null>(null); const [editing,setEditing]=useState<any|null>(null); const [editForm,setEditForm]=useState<any>({});
  const [items,setItems]=useState<any[]>(transactions);
  const [categories,setCategories]=useState<string[]>(DEFAULT_TRANSACTION_CATEGORIES);
  useEffect(()=>{const load=()=>{const saved=localStorage.getItem('juntos-transactions');setItems(saved?JSON.parse(saved):transactions);try{const settings=JSON.parse(localStorage.getItem('juntos-settings')||'{}');const configured=settings.categories;if(Array.isArray(configured))setCategories([...new Set([...DEFAULT_TRANSACTION_CATEGORIES,...configured])])}catch{}};load();window.addEventListener('juntos-transactions-updated',load);window.addEventListener('juntos-cloud-synced',load);return()=>{window.removeEventListener('juntos-transactions-updated',load);window.removeEventListener('juntos-cloud-synced',load)}},[]);
  const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-transactions',JSON.stringify(next));window.dispatchEvent(new Event('juntos-transactions-updated'))};
  const openEdit=(t:any)=>{setEditing(t);setEditForm({...t,value:String(t.value).replace('.',','),dateInput:t.dateInput||(t.date?.includes('-')?t.date:period+'-'+String(t.date).replace(/\D/g,'').padStart(2,'0'))});setOpenMenu(null)};
  const saveEdit=(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(editForm.value).replace(/[.]/g,'').replace(',','.'));if(!editForm.title?.trim()||Number.isNaN(value))return;persist(items.map(x=>x.id===editing.id?{...x,...editForm,title:editForm.title.trim(),value,date:editForm.dateInput?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(editForm.dateInput+'T12:00:00')).replace('.',''):x.date}:x));setEditing(null);appAction('Transação atualizada com sucesso.')};
  const remove=async(t:any)=>{if(await confirmDialog(`Excluir “${t.title}”?`)){persist(items.filter(x=>x.id!==t.id));setOpenMenu(null);appAction('Transação excluída.')}};
  const periodItems=items.filter(t=>!t.dateInput||t.dateInput.startsWith(period));
  const filtered=periodItems.filter(t=>(t.title.toLowerCase().includes(query.toLowerCase())||t.category.toLowerCase().includes(query.toLowerCase()))&&(person==='Todas'||t.person===person));
  const income=periodItems.filter(t=>t.type==='in').reduce((sum,t)=>sum+Number(t.value),0); const expense=periodItems.filter(t=>t.type==='out').reduce((sum,t)=>sum+Number(t.value),0); const result=income-expense;
  return <div className="page-stack"><div className="page-heading"><div><p>Controle financeiro</p><h1>Transações</h1><span>Acompanhe tudo que entra e sai.</span></div><NewTransactionButton onSelect={type=>onNew(type)}/></div><div className="metrics-grid compact"><MetricCard label="Entradas" value={brl(income)} detail="Este mês" icon={TrendingUp} tone="positive"/><MetricCard label="Saídas" value={brl(expense)} detail="Este mês" icon={TrendingDown} tone="negative"/><MetricCard label="Resultado" value={brl(result)} detail={result>=0?'Positivo':'Negativo'} icon={WalletCards} tone="purple"/></div><section className="card table-card"><div className="toolbar"><label className="search"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar transação..."/></label><select className="ghost toolbar-select" value={person} onChange={e=>setPerson(e.target.value)}><option>Todas</option><option value="Rafael">Você</option><option value="Mariana">Parceiro(a)</option><option>Casal</option></select><input className="ghost toolbar-month" type="month" value={period} onChange={e=>setPeriod(e.target.value)}/></div><div className="transactions-detail-table"><div className="transactions-detail-head"><span>Situação</span><span>Descrição</span><span>Categoria</span><span>Conta</span><span>Data da efetivação</span><span>Valor</span><span>Editar</span></div>{filtered.length?filtered.map(t=>{const paid=t.status==='Pago'||t.status==='Efetivada';const situation=paid?'Pago':'Pendente';return <div className="transactions-detail-row" key={t.id}><button type="button" className={`transaction-situation ${situation.toLowerCase()}`} onClick={()=>persist(items.map(item=>item.id===t.id?{...item,status:paid?'Pendente':'Pago',paidAt:paid?null:new Date().toISOString()}:item))} aria-label={`${situation}. Clique para alterar`} title="Clique para alterar a situação">{paid?<Check size={15}/>:<CalendarDays size={15}/>}<span>{situation}</span></button><span className="transaction-description"><i className={`transaction-icon ${t.type}`}>{categoryIconFor(t.category,t.icon)}</i><span><b>{displayTitle(people,t.title)}</b><small>{t.notes||displayPerson(people,t.person)}</small></span></span><span data-label="Categoria">{t.category||'Outros'}</span><span data-label="Conta">{t.account||t.card||'Não informada'}</span><span data-label="Data da efetivação">{paid&&t.paidAt?<>Pago em {new Date(t.paidAt).toLocaleDateString('pt-BR')}</>:t.dateInput?<>Prevista: {new Date(t.dateInput+'T12:00:00').toLocaleDateString('pt-BR')}</>:t.date}</span><strong className={t.type} data-label="Valor">{t.type === 'in' ? '+' : '−'} {brl(t.value)}</strong><button className="icon-button transaction-edit-button" onClick={()=>openEdit(t)} aria-label={`Editar ${t.title}`} title="Editar transação"><Pencil size={17}/></button></div>}):<div className="organizer-empty">Nenhuma transação encontrada.</div>}</div></section>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal edit-transaction-modal" onSubmit={saveEdit}><div className="edit-modal-head"><div><span>EDITAR MOVIMENTAÇÃO</span><h2>Editar transação</h2><p>Atualize os dados do lançamento selecionado.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X size={19}/></button></div><div className="type-switch edit-types"><button type="button" className={editForm.type==='in'?'active':''} onClick={()=>setEditForm({...editForm,type:'in',icon:'↗'})}>Receita</button><button type="button" className={editForm.type==='out'?'active':''} onClick={()=>setEditForm({...editForm,type:'out',icon:'−'})}>Despesa</button></div><div className="edit-form-grid"><label className="field-full">Descrição<input value={editForm.title||''} onChange={e=>setEditForm({...editForm,title:e.target.value})} required/></label><label>Valor (R$)<input value={editForm.value||''} onChange={e=>setEditForm({...editForm,value:formatMoneyInput(e.target.value)})} inputMode="decimal" required/></label><label>Data<input type="date" value={editForm.dateInput||''} onChange={e=>setEditForm({...editForm,dateInput:e.target.value})}/></label><label>Categoria<select value={editForm.category||''} onChange={e=>setEditForm({...editForm,category:e.target.value})}>{categories.map(x=><option key={x}>{x}</option>)}</select></label><label>Pessoa<select value={editForm.person||'Rafael'} onChange={e=>setEditForm({...editForm,person:e.target.value})}><option value="Rafael">Você</option><option value="Mariana">Parceiro(a)</option><option>Casal</option></select></label><label>Situação<select value={editForm.status||'Efetivada'} onChange={e=>setEditForm({...editForm,status:e.target.value,paidAt:e.target.value==='Pago'?(editForm.paidAt||new Date().toISOString()):null})}><option>Pago</option><option>Pendente</option></select></label><label className="field-full">Conta<input value={editForm.account||editForm.card||''} onChange={e=>setEditForm({...editForm,account:e.target.value})} placeholder="Conta ou cartão"/></label></div><div className="edit-modal-actions"><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar alterações</button></div></form></div>}
  </div>;
}

function BudgetsPage(){
  const initial:any[]=[];
  const [items,setItems]=useState<any[]>(initial); const [editing,setEditing]=useState<any|null>(null); const [tx,setTx]=useState<any[]>(transactions); const [period,setPeriod]=useState(()=>new Intl.DateTimeFormat('en-CA').format(new Date()).slice(0,7));
  const categories=['Moradia','Alimentação','Mercado','Restaurante','Delivery','Transporte','Combustível','Aluguel','Condomínio','Internet','Luz','Água','Telefone','Saúde','Educação','Filhos','Viagens','Lazer','Compras','Assinaturas','Investimentos','Dívidas','Seguros','Impostos','Outros'];
  useEffect(()=>{const saved=localStorage.getItem('juntos-budgets');if(saved)setItems(JSON.parse(saved));const load=()=>{const data=localStorage.getItem('juntos-transactions');setTx(data?JSON.parse(data):transactions)};load();window.addEventListener('juntos-transactions-updated',load);return()=>window.removeEventListener('juntos-transactions-updated',load)},[]);
  const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-budgets',JSON.stringify(next))}; const spent=(b:any)=>tx.filter(t=>t.type==='out'&&(t.category===b.category||(b.theme==='fixed'&&['Aluguel','Condomínio','Internet','Luz','Água','Telefone'].includes(t.category)))).reduce((s,t)=>s+Number(t.value),0);
  const openNew=()=>setEditing({id:Date.now(),name:'',category:'Lazer',limit:'',theme:'leisure',icon:'🎯',color:'#7c3aed',isNew:true}); const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,limit:Number(String(editing.limit).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;if(!item.name.trim()||item.limit<=0)return;persist(editing.isNew?[...items,item]:items.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Orçamento criado com sucesso.':'Orçamento atualizado com sucesso.')}; const remove=async()=>{if(editing&&!editing.isNew&&await confirmDialog(`Excluir “${editing.name}”?`)){persist(items.filter(x=>x.id!==editing.id));setEditing(null);appAction('Orçamento excluído.')}};
  const totalLimit=items.reduce((s,x)=>s+Number(x.limit),0),totalSpent=items.reduce((s,x)=>s+spent(x),0);
  return <div className="page-stack budgets-page"><div className="page-heading"><div><p>Planejamento mensal</p><h1>Orçamentos</h1><span>Escolha onde gastar e respeite seus limites.</span></div><div className="budget-actions"><input className="ghost toolbar-month" type="month" value={period} onChange={e=>setPeriod(e.target.value)}/><button className="primary" onClick={openNew}><Plus size={18}/> Novo orçamento</button></div></div><div className="metrics-grid compact"><MetricCard label="Limite planejado" value={brl(totalLimit)} detail="Todos os temas" icon={Target} tone="purple"/><MetricCard label="Valor utilizado" value={brl(totalSpent)} detail={`${Math.round(totalSpent/totalLimit*100)||0}% do total`} icon={TrendingDown} tone="negative"/><MetricCard label="Ainda disponível" value={brl(Math.max(0,totalLimit-totalSpent))} detail="Para o restante do mês" icon={WalletCards} tone="positive"/></div><div className="budget-grid">{items.map(b=>{const used=spent(b),pct=Math.min(100,Math.round(used/b.limit*100)||0),remaining=b.limit-used;return <article className={`card budget-card ${remaining<0?'over':''}`} key={b.id}><button className="budget-edit" onClick={()=>setEditing({...b,limit:String(b.limit).replace('.',',')})} aria-label={`Editar ${b.name}`}><MoreHorizontal size={18}/></button><div className="budget-icon" style={{background:`${b.color}18`,color:b.color}}>{b.icon}</div><span>{b.theme==='fixed'?'DESPESA FIXA':b.theme==='leisure'?'LAZER':b.theme==='saving'?'RESERVA':'VARIÁVEL'}</span><h3>{b.name}</h3><small>{b.category}</small><div className="budget-values"><b>{brl(used)}</b><span>de {brl(b.limit)}</span></div><div className="progress"><span style={{width:`${pct}%`,background:remaining<0?'#c13d4e':b.color}}/></div><div className="budget-foot"><span>{pct}% utilizado</span><strong className={remaining<0?'down':'up'}>{remaining<0?`${brl(Math.abs(remaining))} acima`:`${brl(remaining)} disponível`}</strong></div></article>})}</div>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal budget-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO ORÇAMENTO':'EDITAR ORÇAMENTO'}</span><h2>{editing.isNew?'Criar limite de gastos':'Atualizar limite'}</h2><p>Escolha o tema e quanto deseja gastar.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="budget-edit-grid"><label className="field-full">Nome do orçamento<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} placeholder="Ex.: Lazer de fim de semana" required/></label><label>Tema<select value={editing.theme} onChange={e=>setEditing({...editing,theme:e.target.value})}><option value="fixed">Despesa fixa</option><option value="leisure">Lazer</option><option value="variable">Gasto variável</option><option value="saving">Reserva</option></select></label><label>Categoria<select value={editing.category} onChange={e=>setEditing({...editing,category:e.target.value})}>{categories.map(x=><option key={x}>{x}</option>)}</select></label><label>Limite mensal<input value={editing.limit} onChange={e=>setEditing({...editing,limit:formatMoneyInput(e.target.value)})} placeholder="0,00" inputMode="decimal" required/></label><label>Ícone<input value={editing.icon} onChange={e=>setEditing({...editing,icon:e.target.value})} maxLength={4}/></label><label>Cor<input type="color" value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir orçamento</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar orçamento</button></div></form></div>}
  </div>
}
function AccountsPage({people,setPeople,balances,setBalances}:{people:any;setPeople:any;balances:any;setBalances:any}) {
  const [accounts,setAccounts]=useState<any[]>([]); const [editing,setEditing]=useState<any|null>(null); const [transfer,setTransfer]=useState<any|null>(null);
  useEffect(()=>{const saved=localStorage.getItem('juntos-accounts');setAccounts(saved?JSON.parse(saved):[])},[]);
  const persist=(next:any[])=>{setAccounts(next);localStorage.setItem('juntos-accounts',JSON.stringify(next));const nextBalances={...balances,couple:0,rafael:0,mariana:0,investments:0};next.forEach(a=>{if(a.id in nextBalances)nextBalances[a.id]=Number(a.value)});setBalances(nextBalances);localStorage.setItem('juntos-balances',JSON.stringify(nextBalances))};
  const openNew=()=>setEditing({id:'account-'+Date.now(),name:'',bank:'',type:'Conta corrente',value:'',color:'violet',isNew:true});
  const saveAccount=(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(editing.value).replace(/[.]/g,'').replace(',','.'));if(!editing.name.trim()||!editing.bank.trim()||Number.isNaN(value))return;const account={...editing,name:editing.name.trim(),bank:editing.bank.trim(),value};delete account.isNew;const next=editing.isNew?[...accounts,account]:accounts.map(a=>a.id===account.id?account:a);persist(next);if(account.id==='rafael')setPeople({...people,Rafael:{...people.Rafael,name:account.name}});if(account.id==='mariana')setPeople({...people,Mariana:{...people.Mariana,name:account.name}});setEditing(null);appAction(editing.isNew?'Conta criada com sucesso.':'Conta atualizada em todo o aplicativo.')};
  const deleteAccount=async()=>{if(!editing||!await confirmDialog(`Excluir a conta ${editing.name}?`))return;persist(accounts.filter(a=>a.id!==editing.id));setEditing(null);appAction('Conta excluída.')};
  const saveTransfer=async(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(transfer.value).replace(/[.]/g,'').replace(',','.'));if(!transfer.from||!transfer.to||transfer.from===transfer.to||value<=0)return;const origin=accounts.find(a=>a.id===transfer.from);if(!origin||origin.value<value){await alertDialog('Saldo insuficiente na conta de origem.');return}persist(accounts.map(a=>a.id===transfer.from?{...a,value:a.value-value}:a.id===transfer.to?{...a,value:a.value+value}:a));setTransfer(null);appAction('Transferência concluída com sucesso.')};
  const total=accounts.reduce((sum,a)=>sum+Number(a.value||0),0);
  return <div className="page-stack"><div className="page-heading"><div><p>Patrimônio</p><h1>Contas</h1><span>Todos os saldos em um só lugar.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Nova conta</button></div><div className="account-grid">{accounts.length?accounts.map(a=><article className="card account" key={a.id}><div className={`bank-icon ${a.color}`}><Landmark/></div><button className="icon-button" onClick={()=>setEditing({...a,value:String(a.value).replace('.',',')})} aria-label={`Editar ${a.name}`}><MoreHorizontal size={18}/></button><span>{a.bank}</span><h3>{a.name}</h3><small>{a.type}</small><strong>{brl(a.value)}</strong><div className="account-foot"><span>Sem movimentações</span></div></article>):<div className="organizer-empty">Nenhuma conta cadastrada.</div>}</div><section className="card table-card"><div className="section-title"><div><h3>Visão consolidada</h3><p>Saldo por instituição</p></div><button className="ghost" disabled={accounts.length<2} onClick={()=>setTransfer({from:accounts[0]?.id||'',to:accounts[1]?.id||'',value:''})}>Transferir entre contas</button></div><div className="metrics-grid compact"><MetricCard label="Saldo total" value={brl(total)} detail={`${accounts.length} contas cadastradas`} icon={WalletCards} tone="purple"/><MetricCard label="Entradas" value={brl(0)} detail="Sem movimentações" icon={TrendingUp} tone="positive"/><MetricCard label="Saídas" value={brl(0)} detail="Sem movimentações" icon={TrendingDown} tone="negative"/></div><div className="bar-wrap"><ResponsiveContainer width="100%" height="100%"><ReBarChart data={accounts} layout="vertical" margin={{left:20,right:30}}><CartesianGrid strokeDasharray="4 4" horizontal={false}/><XAxis type="number" hide/><YAxis type="category" dataKey="bank" axisLine={false} tickLine={false}/><Tooltip formatter={(v)=>brl(Number(v))}/><Bar dataKey="value" fill="#7f2854" radius={[0,8,8,0]}/></ReBarChart></ResponsiveContainer></div></section>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal account-editor" onSubmit={saveAccount}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVA CONTA':'EDITAR CONTA'}</span><h2>{editing.isNew?'Adicionar conta':'Configurar conta'}</h2><p>Atualize todas as informações e o saldo.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X size={19}/></button></div><div className="account-edit-grid"><label>Nome da conta<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} required/></label><label>Instituição<input value={editing.bank} onChange={e=>setEditing({...editing,bank:e.target.value})} placeholder="Ex.: Nubank" required/></label><label>Tipo<select value={editing.type} onChange={e=>setEditing({...editing,type:e.target.value})}><option>Conta corrente</option><option>Conta individual</option><option>Carteira</option><option>Investimentos</option><option>Poupança</option></select></label><label>Saldo<input value={editing.value} onChange={e=>setEditing({...editing,value:formatMoneyInput(e.target.value)})} inputMode="decimal" required/></label><label>Cor<select value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}><option value="violet">Roxo</option><option value="orange">Laranja</option><option value="amber">Amarelo</option><option value="dark">Preto</option></select></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger delete-account" onClick={deleteAccount}>Excluir conta</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar conta</button></div></form></div>}
    {transfer&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setTransfer(null)}><form className="modal transfer-modal" onSubmit={saveTransfer}><div className="edit-modal-head"><div><span>MOVIMENTAÇÃO INTERNA</span><h2>Transferir entre contas</h2><p>O valor será debitado da origem e creditado no destino.</p></div><button type="button" className="icon-button" onClick={()=>setTransfer(null)}><X size={19}/></button></div><div className="account-edit-grid"><label>Conta de origem<select value={transfer.from} onChange={e=>setTransfer({...transfer,from:e.target.value})}>{accounts.map(a=><option value={a.id} key={a.id}>{a.name} — {brl(a.value)}</option>)}</select></label><label>Conta de destino<select value={transfer.to} onChange={e=>setTransfer({...transfer,to:e.target.value})}>{accounts.map(a=><option value={a.id} key={a.id}>{a.name}</option>)}</select></label><label className="field-full">Valor da transferência<input value={transfer.value} onChange={e=>setTransfer({...transfer,value:formatMoneyInput(e.target.value)})} placeholder="0,00" inputMode="decimal" required/></label></div><div className="edit-modal-actions"><span/><button type="button" className="ghost" onClick={()=>setTransfer(null)}>Cancelar</button><button className="primary">Confirmar transferência</button></div></form></div>}
  </div>
}

