const bankLogo=(domain?:string)=>domain?`https://www.google.com/s2/favicons?domain=${domain}&sz=64`:'';
function BankPicker({editing,setEditing}:{editing:any,setEditing:(value:any)=>void}){
  const [open,setOpen]=useState(false); const [galleryOpen,setGalleryOpen]=useState(false); const [galleryQuery,setGalleryQuery]=useState(''); const normalize=(value:string)=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(); const query=normalize(editing.bank||'');
  const matches=brazilianBanks.filter(bank=>normalize(`${bank.name} ${bank.aliases}`).includes(query)).slice(0,8);
  const galleryBanks=brazilianBanks.filter(bank=>normalize(`${bank.name} ${bank.aliases}`).includes(normalize(galleryQuery)));
  const choose=(bank:typeof brazilianBanks[number])=>{setEditing({...editing,bank:bank.name,bankDomain:bank.domain,bankTheme:bank.theme});setOpen(false);setGalleryOpen(false);setGalleryQuery('')};
  return <><label className="bank-picker">Instituição<div className="bank-input-wrap"><button type="button" className="bank-icon-trigger" onClick={()=>{setOpen(false);setGalleryOpen(true)}} aria-label="Selecionar ícone do cartão" title="Selecionar banco">{editing.bankDomain?<img src={bankLogo(editing.bankDomain)} alt=""/>:<WalletCards size={20}/>}</button><input value={editing.bank} onFocus={()=>setOpen(true)} onChange={e=>setEditing({...editing,bank:e.target.value,bankDomain:'',bankTheme:'neutral'})} placeholder="Digite o nome do banco" autoComplete="off" required/></div>{open&&query&&<div className="bank-suggestions">{matches.length?matches.map(bank=><button type="button" key={bank.name} onMouseDown={e=>e.preventDefault()} onClick={()=>choose(bank)}><img src={bankLogo(bank.domain)} alt=""/><span><b>{bank.name}</b><small>{bank.domain}</small></span></button>):<span className="bank-no-results">Nenhum banco conhecido encontrado. Você pode usar este nome.</span>}</div>}</label>{galleryOpen&&<div className="modal-backdrop bank-gallery-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setGalleryOpen(false)}><div className="modal bank-gallery"><div className="edit-modal-head"><div><span>ÍCONE DO CARTÃO</span><h2>Selecionar banco</h2><p>Escolha uma instituição para usar seu ícone no cartão.</p></div><button type="button" className="icon-button" onClick={()=>setGalleryOpen(false)} aria-label="Fechar"><X/></button></div><label className="bank-gallery-search"><Search size={18}/><input value={galleryQuery} onChange={e=>setGalleryQuery(e.target.value)} placeholder="Buscar banco..." autoFocus/></label><div className="bank-gallery-grid">{galleryBanks.map(bank=><button type="button" className={editing.bankDomain===bank.domain?'active':''} key={bank.name} onClick={()=>choose(bank)}><span><img src={bankLogo(bank.domain)} alt=""/></span><b>{bank.name}</b></button>)}</div>{!galleryBanks.length&&<div className="bank-gallery-empty">Nenhum banco encontrado.</div>}</div></div>}</>;
}
function CardsPage({people,onTransaction}:{people:any;onTransaction:(data:any)=>void}){
  const defaultCards:any[]=[];
  const [cards,setCards]=useState<any[]>(defaultCards); const [selectedId,setSelectedId]=useState('nubank-4821'); const [editing,setEditing]=useState<any|null>(null); const [details,setDetails]=useState(false); const [openCardMenu,setOpenCardMenu]=useState<string|null>(null); const [cardTool,setCardTool]=useState<any|null>(null); const [purchases,setPurchases]=useState<any[]>(transactions.filter(t=>t.type==='out'));
  useEffect(()=>{const loadCards=()=>{const saved=localStorage.getItem('juntos-cards');if(saved){const parsed=JSON.parse(saved);setCards(parsed);setSelectedId(current=>parsed.some((item:any)=>item.id===current)?current:(parsed[0]?.id||''))}};const load=()=>{const tx=localStorage.getItem('juntos-transactions');setPurchases((tx?JSON.parse(tx):transactions).filter((t:any)=>t.type==='out'))};loadCards();load();window.addEventListener('juntos-transactions-updated',load);window.addEventListener('juntos-cards-updated',loadCards);return()=>{window.removeEventListener('juntos-transactions-updated',load);window.removeEventListener('juntos-cards-updated',loadCards)}},[]);
  const persist=(next:any[])=>{setCards(next);localStorage.setItem('juntos-cards',JSON.stringify(next));window.dispatchEvent(new Event('juntos-cards-updated'))}; const card=cards.find(c=>c.id===selectedId)||cards[0];
  const cardLabel=(item:any)=>item.last4 ? item.bank+' final '+item.last4 : item.bank;
  const cardPurchases=card?purchases.filter(transaction=>transaction.card===cardLabel(card)):[];
  const openNew=()=>setEditing({id:'card-'+Date.now(),bank:'',last4:'',holder:people.Rafael.name.toUpperCase()||'',invoice:'0',limit:'0',closing:new Date().toISOString().slice(0,10),dueDay:'10',future:'0',bankDomain:'',bankTheme:'neutral',isNew:true});
  const saveCard=(e:React.FormEvent)=>{e.preventDefault();const clean={...editing,invoice:Number(String(editing.invoice).replace(/[.]/g,'').replace(',','.')),limit:Number(String(editing.limit).replace(/[.]/g,'').replace(',','.')),future:Number(String(editing.future).replace(/[.]/g,'').replace(',','.')),dueDay:Number(editing.dueDay)};delete clean.isNew;if(!clean.bank.trim()||(clean.last4&&clean.last4.length!==4)||!clean.holder.trim()||clean.limit<=0||!clean.closing||clean.dueDay<1||clean.dueDay>31){appAction('Preencha os dados obrigatórios, informe um limite maior que zero e um vencimento entre os dias 1 e 31.');return}const next=editing.isNew?[...cards,clean]:cards.map(c=>c.id===clean.id?clean:c);persist(next);setSelectedId(clean.id);setEditing(null);appAction(editing.isNew?'Cartão criado com sucesso.':'Cartão atualizado com sucesso.')};
  const removeCard=async()=>{if(!editing||!await confirmDialog(`Excluir o cartão ${editing.bank}?`))return;const next=cards.filter(c=>c.id!==editing.id);persist(next);setSelectedId(next[0]?.id||'');setEditing(null);appAction('Cartão excluído.')};
  const deleteCard=async(item:any)=>{if(!await confirmDialog(`Excluir o cartão ${item.bank}?`))return;const next=cards.filter(c=>c.id!==item.id);persist(next);if(item.id===card.id)setSelectedId(next[0]?.id||'');setCardTool(null);appAction('Cartão excluído.');};
  const pay=async()=>{if(!card||!await confirmDialog(`Confirmar pagamento de ${brl(card.invoice)}?`))return;const value=Number(card.invoice);persist(cards.map(c=>c.id===card.id?{...c,invoice:0}:c));if(value>0)onTransaction({title:`Pagamento da fatura - ${card.bank}`,category:'Dívidas',person:'Rafael',account:'Carteira',payment:'Boleto',card:'',date:new Intl.DateTimeFormat('en-CA').format(new Date()),value,type:'out',icon:'💳',schedule:'once'});appAction('Fatura paga e registrada nas transações.')};
  if(!card)return <div className="page-stack"><div className="page-heading"><div><p>Crédito</p><h1>Cartões</h1><span>Nenhum cartão cadastrado.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Novo cartão</button></div>{editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal card-editor" onSubmit={saveCard}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO CARTÃO':'EDITAR CARTÃO'}</span><h2>{editing.isNew?'Adicionar cartão':'Configurar cartão'}</h2><p>Edite todos os dados, limites e datas.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="card-edit-grid"><BankPicker editing={editing} setEditing={setEditing}/><label>Titular<input value={editing.holder} onChange={e=>setEditing({...editing,holder:e.target.value})} required/></label><label>Fatura atual<input value={editing.invoice} onChange={e=>setEditing({...editing,invoice:formatMoneyInput(e.target.value)})}/></label><label>Limite total<input value={editing.limit} onChange={e=>setEditing({...editing,limit:formatMoneyInput(e.target.value)})}/></label><label>Próximo fechamento<input type="date" value={editing.closing} onChange={e=>setEditing({...editing,closing:e.target.value})}/></label><label>Dia do vencimento<input type="number" min="1" max="31" value={editing.dueDay||''} onChange={e=>setEditing({...editing,dueDay:e.target.value.replace(/\D/g,'')})} placeholder="Ex.: 10" required/></label><label>Parcelas futuras<input value={editing.future} onChange={e=>setEditing({...editing,future:formatMoneyInput(e.target.value)})}/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={removeCard}>Excluir cartão</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar cartão</button></div></form></div>}</div>;
  const used=Math.min(100,Math.round(card.invoice/card.limit*100)||0); const closingLabel=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long'}).format(new Date(card.closing+'T12:00:00'));
  return <div className="page-stack"><div className="page-heading"><div><p>Crédito</p><h1>Cartões</h1><span>Limites e faturas sob controle.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Novo cartão</button></div><section className="registered-cards-section"><div className="section-title"><div><h3>Cartões cadastrados</h3><p>{cards.length} {cards.length===1?'cartão disponível':'cartões disponíveis'} · selecione para ver as compras</p></div></div><div className="registered-cards-grid">{cards.map(item=>{const invoice=Number(item.invoice)||0;const limit=Number(item.limit)||0;const available=Math.max(0,limit-invoice);const usedPct=Math.min(100,Math.round(invoice/limit*100)||0);const availablePct=Math.max(0,100-usedPct);const itemPurchases=purchases.filter(transaction=>transaction.card===cardLabel(item));const itemClosing=item.closing?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(item.closing+'T12:00:00')):'Não informado';return <article className={`registered-card card bank-theme-${item.bankTheme||item.color||'neutral'} ${item.id===card.id?'active':''}`} key={item.id} onClick={()=>setSelectedId(item.id)}><div className="registered-card-head"><span className="card-bank-brand">{item.bankDomain&&<img src={bankLogo(item.bankDomain)} alt=""/>}<b>{item.bank}</b></span><div className="registered-card-head-tools" onClick={event=>event.stopPropagation()}><i className={invoice>0?'open':'closed'}>{invoice>0?'Fatura aberta':'Fatura fechada'}</i><button type="button" className="card-quick-add" onClick={()=>window.dispatchEvent(new CustomEvent('juntos-card-expense',{detail:{card:cardLabel(item)}}))} aria-label={`Adicionar despesa em ${item.bank}`} title="Adicionar despesa"><Plus size={17}/></button><div className="card-menu-wrap"><button type="button" className="card-menu-trigger" onClick={()=>setOpenCardMenu(openCardMenu===item.id?null:item.id)} aria-label={`Opções de ${item.bank}`}><MoreHorizontal size={19}/></button>{openCardMenu===item.id&&<div className="card-options-menu"><button type="button" onClick={()=>{setEditing({...item,invoice:String(item.invoice).replace('.',','),limit:String(item.limit).replace('.',','),future:String(item.future).replace('.',',')});setOpenCardMenu(null)}}>Editar</button><button type="button" onClick={()=>{setCardTool({type:'adjust',card:item,value:String(invoice).replace('.',',')});setOpenCardMenu(null)}}>Reajustar fatura</button><button type="button" onClick={()=>{setCardTool({type:'history',card:item});setOpenCardMenu(null)}}>Histórico</button><button type="button" onClick={()=>{setCardTool({type:'details',card:item});setOpenCardMenu(null)}}>Detalhes</button><button type="button" onClick={()=>{setCardTool({type:'evolution',card:item});setOpenCardMenu(null)}}>Evolução mensal</button><button type="button" onClick={()=>{setCardTool({type:'calculator',card:item,value:'',installments:'1',interest:'0'});setOpenCardMenu(null)}}>Calculadora</button><button type="button" className="danger" onClick={()=>{setOpenCardMenu(null);deleteCard(item)}}>Excluir</button></div>}</div></div></div><span className="registered-card-holder">Titular: <b>{item.holder}</b></span><div className="registered-card-values"><span><small>Limite total</small><strong>{brl(limit)}</strong></span><span><small>Fatura atual</small><strong>{brl(invoice)}</strong></span><span><small>Disponível</small><strong>{brl(available)}</strong></span></div><div className="registered-card-usage"><div><span>Usado: <b>{brl(invoice)} ({usedPct}%)</b></span><span>Disponível: <b>{brl(available)} ({availablePct}%)</b></span></div><div className="registered-card-progress"><span style={{width:`${usedPct}%`}}/></div></div><div className="registered-card-foot"><span><CalendarDays size={15}/><small>Próximo fechamento</small><b>{itemClosing}</b></span><span><ReceiptText size={15}/><small>Compras no cartão</small><b>{itemPurchases.length}</b></span></div></article>})}</div></section><section className="card table-card"><div className="section-title"><div><h3>Compras no cartão</h3><p>Fatura atual</p></div><button className="text-button" onClick={()=>appAction({page:'Transações'})}>Ver fatura completa <ArrowRight size={15}/></button></div><div className="transaction-list large">{cardPurchases.length?cardPurchases.map(t=><div className="transaction" key={t.id}><div className="transaction-icon out">{categoryIconFor(t.category,t.icon)}</div><div className="transaction-name"><b>{displayTitle(people,t.title)}</b><span>{t.category}{t.card?` · ${t.card}`:''}</span><small className="transaction-mobile-date">{t.date}</small></div><span className="person-pill">{displayPerson(people,t.person)}</span><div className="transaction-date">{t.date}</div><strong>− {brl(t.value)}</strong></div>):<div className="organizer-empty">Nenhuma compra cadastrada neste cartão.</div>}</div></section>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal card-editor" onSubmit={saveCard}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO CARTÃO':'EDITAR CARTÃO'}</span><h2>{editing.isNew?'Adicionar cartão':'Configurar cartão'}</h2><p>Edite todos os dados, limites e datas.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="card-edit-grid"><BankPicker editing={editing} setEditing={setEditing}/><label>Titular<input value={editing.holder} onChange={e=>setEditing({...editing,holder:e.target.value})} required/></label><label>Fatura atual<input value={editing.invoice} onChange={e=>setEditing({...editing,invoice:formatMoneyInput(e.target.value)})}/></label><label>Limite total<input value={editing.limit} onChange={e=>setEditing({...editing,limit:formatMoneyInput(e.target.value)})}/></label><label>Próximo fechamento<input type="date" value={editing.closing} onChange={e=>setEditing({...editing,closing:e.target.value})}/></label><label>Dia do vencimento<input type="number" min="1" max="31" value={editing.dueDay||''} onChange={e=>setEditing({...editing,dueDay:e.target.value.replace(/\D/g,'')})} placeholder="Ex.: 10" required/></label><label>Parcelas futuras<input value={editing.future} onChange={e=>setEditing({...editing,future:formatMoneyInput(e.target.value)})}/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={removeCard}>Excluir cartão</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar cartão</button></div></form></div>}
    {details&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setDetails(false)}><div className="modal card-details"><div className="edit-modal-head"><div><span>RESUMO DO CARTÃO</span><h2>{card.bank} {card.last4?`•••• ${card.last4}`:''}</h2></div><button className="icon-button" onClick={()=>setDetails(false)}><X/></button></div><div className="details-list"><div><span>Fatura atual</span><b>{brl(card.invoice)}</b></div><div><span>Limite total</span><b>{brl(card.limit)}</b></div><div><span>Limite disponível</span><b>{brl(Math.max(0,card.limit-card.invoice))}</b></div><div><span>Próximo fechamento</span><b>{closingLabel}</b></div><div><span>Vencimento</span><b>{card.dueDay?'Dia '+card.dueDay:'Não informado'}</b></div><div><span>Parcelas futuras</span><b>{brl(card.future)}</b></div></div><div className="edit-modal-actions"><span/><button className="primary" onClick={()=>setDetails(false)}>Fechar</button></div></div></div>}
    {cardTool&&<div className="modal-backdrop" onMouseDown={event=>event.target===event.currentTarget&&setCardTool(null)}><div className="modal card-tool-modal"><div className="edit-modal-head"><div><span>GESTÃO DO CARTÃO</span><h2>{cardTool.type==='adjust'?'Reajustar fatura':cardTool.type==='history'?'Histórico de compras':cardTool.type==='details'?'Detalhes do cartão':cardTool.type==='evolution'?'Evolução mensal':'Calculadora de compras'}</h2><p>{cardTool.card.bank} · {cardTool.card.holder}</p></div><button type="button" className="icon-button" onClick={()=>setCardTool(null)}><X/></button></div>{cardTool.type==='adjust'&&<form className="card-tool-form" onSubmit={event=>{event.preventDefault();const value=Number(String(cardTool.value).replace(/[.]/g,'').replace(',','.'));if(value<0)return;persist(cards.map(item=>item.id===cardTool.card.id?{...item,invoice:value}:item));setCardTool(null);appAction('Fatura reajustada com sucesso.')}}><label>Novo valor da fatura<input value={cardTool.value} onChange={event=>setCardTool({...cardTool,value:formatMoneyInput(event.target.value)})} inputMode="decimal" autoFocus required/></label><div className="card-tool-actions"><button type="button" className="ghost" onClick={()=>setCardTool(null)}>Cancelar</button><button className="primary">Salvar reajuste</button></div></form>}{cardTool.type==='history'&&<div className="card-tool-content">{purchases.filter(item=>item.card===cardLabel(cardTool.card)).length?purchases.filter(item=>item.card===cardLabel(cardTool.card)).map(item=><div className="card-history-row" key={item.id}><span><b>{displayTitle(people,item.title)}</b><small>{item.category} · {item.date}</small></span><strong>{brl(item.value)}</strong></div>):<div className="organizer-empty">Nenhuma compra registrada neste cartão.</div>}</div>}{cardTool.type==='details'&&<div className="card-tool-content details-list"><div><span>Titular</span><b>{cardTool.card.holder}</b></div><div><span>Limite total</span><b>{brl(Number(cardTool.card.limit)||0)}</b></div><div><span>Fatura atual</span><b>{brl(Number(cardTool.card.invoice)||0)}</b></div><div><span>Status</span><b>{Number(cardTool.card.invoice)>0?'Aberta':'Fechada'}</b></div><div><span>Limite disponível</span><b>{brl(Math.max(0,Number(cardTool.card.limit)-Number(cardTool.card.invoice)))}</b></div><div><span>Próximo fechamento</span><b>{cardTool.card.closing?new Date(cardTool.card.closing+'T12:00:00').toLocaleDateString('pt-BR'):'Não informado'}</b></div><div><span>Vencimento</span><b>{cardTool.card.dueDay?'Dia '+cardTool.card.dueDay:'Não informado'}</b></div></div>}{cardTool.type==='evolution'&&<div className="card-tool-content">{(()=>{const monthly=new Map<string,number>();purchases.filter(item=>item.card===cardLabel(cardTool.card)&&item.dateInput).forEach(item=>{const month=item.dateInput.slice(0,7);monthly.set(month,(monthly.get(month)||0)+Number(item.value||0))});const rows=[...monthly.entries()].sort((a,b)=>a[0].localeCompare(b[0])).slice(-6);const max=Math.max(...rows.map(row=>row[1]),1);return rows.length?<div className="monthly-evolution">{rows.map(([month,value])=><div key={month}><span>{new Date(month+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'short',year:'2-digit'})}</span><div><i style={{width:`${value/max*100}%`}}/></div><b>{brl(value)}</b></div>)}</div>:<div className="organizer-empty">Ainda não há compras com data suficiente para calcular a evolução.</div>})()}</div>}{cardTool.type==='calculator'&&<div className="card-tool-form"><label>Valor da compra<input value={cardTool.value} onChange={event=>setCardTool({...cardTool,value:formatMoneyInput(event.target.value)})} inputMode="decimal" placeholder="0,00"/></label><label>Parcelas<input type="number" min="1" max="48" value={cardTool.installments} onChange={event=>setCardTool({...cardTool,installments:event.target.value})}/></label><label>Juros totais (%)<input value={cardTool.interest} onChange={event=>setCardTool({...cardTool,interest:event.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal"/></label>{(()=>{const value=Number(String(cardTool.value).replace(/[.]/g,'').replace(',','.'))||0;const installments=Math.max(1,Number(cardTool.installments)||1);const interest=Number(String(cardTool.interest).replace(',','.'))||0;const total=value*(1+interest/100);return <div className="calculator-result"><span>Total estimado<b>{brl(total)}</b></span><span>Valor por parcela<b>{brl(total/installments)} × {installments}</b></span><span>Limite após a compra<b>{brl(Math.max(0,Number(cardTool.card.limit)-Number(cardTool.card.invoice)-total))}</b></span></div>})()}</div>}</div></div>}  </div>
}

function GoalsPage({onTransaction}:{onTransaction:(data:any)=>void}){
  const initialGoals:any[]=[];
  const [items,setItems]=useState<any[]>(initialGoals); const [editing,setEditing]=useState<any|null>(null); const [contribution,setContribution]=useState<any|null>(null);
  useEffect(()=>{const saved=localStorage.getItem('juntos-goals');if(saved)setItems(JSON.parse(saved))},[]); const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-goals',JSON.stringify(next));window.dispatchEvent(new Event('juntos-goals-updated'))};
  const openNew=()=>setEditing({id:Date.now(),title:'',emoji:'🎯',current:'0',total:'',color:'#7c3aed',date:'Dez 2026',isNew:true});
  const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,current:Number(String(editing.current).replace(/[.]/g,'').replace(',','.')),total:Number(String(editing.total).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;if(!item.title.trim()||item.total<=0)return;persist(editing.isNew?[...items,item]:items.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Meta criada com sucesso.':'Meta atualizada com sucesso.')};
  const remove=async()=>{if(editing&&!editing.isNew&&await confirmDialog(`Excluir a meta “${editing.title}”?`)){persist(items.filter(x=>x.id!==editing.id));setEditing(null);appAction('Meta excluída.')}};
  const addMoney=(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(contribution.value).replace(/[.]/g,'').replace(',','.'));if(value<=0)return;const goal=contribution.goal;persist(items.map(x=>x.id===goal.id?{...x,current:x.current+value}:x));onTransaction({title:`Aporte na meta - ${goal.title}`,category:'Investimentos',person:'Rafael',account:'Carteira',payment:'Transferência',card:'',date:new Intl.DateTimeFormat('en-CA').format(new Date()),value,type:'out',icon:goal.emoji||'🎯',schedule:'once'});setContribution(null);appAction('Aporte registrado nas transações.')};
  return <div className="page-stack"><div className="page-heading"><div><p>Meus objetivos</p><h1>Metas</h1><span>Cada passo aproxima você do futuro.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Nova meta</button></div><div className="goal-page-grid">{items.map(g=>{const pct=Math.min(100,Math.round(g.current/g.total*100)||0);return <article className="card big-goal" key={g.id}><button className="goal-cover goal-cover-button" style={{background:`linear-gradient(135deg,${g.color},#24131e)`}} onClick={()=>setEditing({...g,current:String(g.current).replace('.',','),total:String(g.total).replace('.',',')})}><span>{g.emoji}</span><b>{pct}%</b><small>Clique para editar</small></button><div className="goal-body"><h3>{g.title}</h3><p>Previsão: {g.date}</p><div className="progress"><span style={{width:`${pct}%`,background:g.color}}/></div><div><b>{brl(g.current)}</b><span>Faltam {brl(Math.max(0,g.total-g.current))}</span></div><button className="ghost" onClick={()=>setContribution({goal:g,value:''})}>Adicionar dinheiro</button></div></article>})}</div>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal goal-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVA META':'EDITAR META'}</span><h2>{editing.isNew?'Criar uma meta':'Atualizar meta'}</h2><p>Personalize o objetivo e acompanhe o progresso.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="goal-edit-grid"><label className="field-full">Nome da meta<input value={editing.title} onChange={e=>setEditing({...editing,title:e.target.value})} placeholder="Ex.: Viagem para Itália" required/></label><label>Ícone<input value={editing.emoji} onChange={e=>setEditing({...editing,emoji:e.target.value})} maxLength={4}/></label><label>Cor<input type="color" value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}/></label><label>Valor guardado<input value={editing.current} onChange={e=>setEditing({...editing,current:formatMoneyInput(e.target.value)})} inputMode="decimal"/></label><label>Valor da meta<input value={editing.total} onChange={e=>setEditing({...editing,total:formatMoneyInput(e.target.value)})} inputMode="decimal" required/></label><label className="field-full">Previsão de conclusão<input value={editing.date} onChange={e=>setEditing({...editing,date:e.target.value})} placeholder="Ex.: Novembro de 2027"/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir meta</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar meta</button></div></form></div>}
    {contribution&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setContribution(null)}><form className="modal contribution-modal" onSubmit={addMoney}><div className="edit-modal-head"><div><span>NOVO APORTE</span><h2>Adicionar dinheiro</h2><p>{contribution.goal.emoji} {contribution.goal.title}</p></div><button type="button" className="icon-button" onClick={()=>setContribution(null)}><X/></button></div><div className="goal-edit-grid"><label className="field-full">Valor do aporte<input value={contribution.value} onChange={e=>setContribution({...contribution,value:formatMoneyInput(e.target.value)})} placeholder="0,00" inputMode="decimal" autoFocus required/></label></div><div className="edit-modal-actions"><span/><button type="button" className="ghost" onClick={()=>setContribution(null)}>Cancelar</button><button className="primary">Confirmar aporte</button></div></form></div>}
  </div>
}

function CalendarPage({people}:{people:any}){
  const initialEvents:any[]=[];
  const [month,setMonth]=useState(new Date()); const [events,setEvents]=useState<any[]>(initialEvents); const [editing,setEditing]=useState<any|null>(null);
  useEffect(()=>{const saved=localStorage.getItem('juntos-calendar-events');if(saved)setEvents(JSON.parse(saved))},[]);
  const persist=(next:any[])=>{setEvents(next);localStorage.setItem('juntos-calendar-events',JSON.stringify(next));window.dispatchEvent(new Event('juntos-calendar-updated'))};
  const year=month.getFullYear(),monthIndex=month.getMonth(),daysInMonth=new Date(year,monthIndex+1,0).getDate(),startDay=new Date(year,monthIndex,1).getDay(); const cells=Array.from({length:42},(_,i)=>i-startDay+1); const monthKey=`${year}-${String(monthIndex+1).padStart(2,'0')}`;
  const openNew=(date?:string)=>setEditing({id:Date.now(),title:'',date:date||`${monthKey}-${String(Math.min(new Date().getDate(),daysInMonth)).padStart(2,'0')}`,type:'bill',value:'',person:'Rafael',notes:'',isNew:true});
  const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,value:Number(String(editing.value||0).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;persist(editing.isNew?[...events,item]:events.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Evento criado no calendário.':'Evento atualizado com sucesso.')};
  const remove=async()=>{if(editing&&!editing.isNew&&await confirmDialog(`Excluir “${editing.title}”?`)){persist(events.filter(x=>x.id!==editing.id));setEditing(null);appAction('Evento excluído do calendário.')}};
  const monthEvents=events.filter(e=>e.date.startsWith(monthKey)); const upcoming=[...events].filter(e=>e.date>=`${monthKey}-01`).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5); const title=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(month).replace(/^./,x=>x.toUpperCase());
  return <div className="page-stack"><div className="page-heading"><div><p>Minha agenda</p><h1>Calendário financeiro</h1><span>Nenhum compromisso fica para trás.</span></div><button className="primary" onClick={()=>openNew()}><Plus size={18}/> Novo evento</button></div><div className="calendar-layout"><section className="card calendar"><div className="calendar-head"><button className="icon-button" onClick={()=>setMonth(new Date(year,monthIndex-1,1))} aria-label="Mês anterior">‹</button><h3>{title}</h3><button className="icon-button" onClick={()=>setMonth(new Date(year,monthIndex+1,1))} aria-label="Próximo mês">›</button><button className="ghost" onClick={()=>setMonth(new Date())}>Hoje</button></div><div className="weekdays">{['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=><b key={x}>{x}</b>)}</div><div className="days">{cells.map((day,i)=>{const valid=day>=1&&day<=daysInMonth;const date=valid?`${monthKey}-${String(day).padStart(2,'0')}`:'';const dayEvents=valid?monthEvents.filter(e=>e.date===date):[];return <div className={!valid?'muted':date===new Date().toISOString().slice(0,10)?'today':''} key={i} onDoubleClick={()=>valid&&openNew(date)}><button className="day-number" onClick={()=>valid&&openNew(date)} disabled={!valid}>{valid?day:''}</button>{dayEvents.map(e=><button className={`calendar-event ${e.type}`} onClick={()=>setEditing({...e,value:String(e.value).replace('.',',')})} key={e.id}>{e.title}</button>)}</div>})}</div><small className="calendar-hint">Clique no número do dia para adicionar. Clique no evento para editar.</small></section><aside className="card agenda"><h3>Próximos eventos</h3>{upcoming.length?upcoming.map(e=><button className="agenda-date" onClick={()=>setEditing({...e,value:String(e.value).replace('.',',')})} key={e.id}><b>{e.date.slice(-2)}</b><span>{new Intl.DateTimeFormat('pt-BR',{weekday:'short'}).format(new Date(e.date+'T12:00:00')).toUpperCase()}<small>{e.title}</small></span><strong>{e.value?brl(e.value):'—'}</strong></button>):<p className="agenda-empty">Nenhum evento agendado.</p>}<div className="ai-mini"><Sparkles/><p><b>Agenda organizada!</b> Clique em qualquer compromisso para atualizar.</p></div></aside></div>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal calendar-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO EVENTO':'EDITAR EVENTO'}</span><h2>{editing.isNew?'Adicionar compromisso':'Atualizar compromisso'}</h2><p>Organize datas, valores e responsáveis.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="calendar-edit-grid"><label className="field-full">Título<input value={editing.title} onChange={e=>setEditing({...editing,title:e.target.value})} placeholder="Ex.: Conta de energia" required/></label><label>Data<input type="date" value={editing.date} onChange={e=>setEditing({...editing,date:e.target.value})} required/></label><label>Tipo<select value={editing.type} onChange={e=>setEditing({...editing,type:e.target.value})}><option value="bill">Conta</option><option value="income">Receita</option><option value="card">Cartão</option><option value="sub">Assinatura</option><option value="goal">Meta</option></select></label><label>Valor<input value={editing.value} onChange={e=>setEditing({...editing,value:formatMoneyInput(e.target.value)})} placeholder="0,00" inputMode="decimal"/></label><label>Responsável<select value={editing.person} onChange={e=>setEditing({...editing,person:e.target.value})}><option value="Rafael">Você</option></select></label><label className="field-full">Observações<textarea value={editing.notes||''} onChange={e=>setEditing({...editing,notes:e.target.value})} placeholder="Detalhes opcionais" rows={3}/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir evento</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar evento</button></div></form></div>}
  </div>
}

